/*
 * 자폭용(kill-switch) service worker.
 *
 * 2025-12에 배포했던 Chirpy 블로그는 PWA 기능이 켜져 있어서, 그때 방문한 브라우저에
 * 이 주소(/sw.min.js)로 service worker 가 설치되었다. 그 service worker 는 서버보다
 * 자기가 저장해둔 사본을 먼저 보여주기 때문에, 사이트를 통째로 바꿔도 예전 블로그가
 * 계속 보인다. 일반 캐시와 달리 방문자가 직접 지우기 전에는 사라지지 않는다.
 *
 * 그래서 같은 주소에 아무것도 캐시하지 않고 자기 자신을 등록 해제하는 파일을 올려둔다.
 * 예전 방문자가 다시 접속하면 브라우저가 이 파일을 새로 받아가고, 아래 코드가
 * 오프라인 캐시를 전부 지운 뒤 스스로 등록을 해제한 다음 페이지를 새로고침한다.
 *
 * 현재 사이트는 service worker 를 등록하지 않는다. 이 파일은 예전 방문자를 정리하기
 * 위한 용도이므로, 한동안(최소 몇 달) 지우지 말 것.
 */

self.addEventListener('install', () => {
  // 대기하지 않고 곧바로 이 버전으로 교체
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // 1. 예전 블로그가 저장해둔 오프라인 캐시를 전부 삭제
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));

      // 2. 자기 자신을 등록 해제
      await self.registration.unregister();

      // 3. 열려 있는 탭들을 새로고침해서 최신 페이지를 받아가게 함
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});

// 캐시를 쓰지 않고 항상 네트워크에서 가져온다
self.addEventListener('fetch', (event) => {
  event.respondWith(fetch(event.request));
});
